import type { Condition, FieldEntry, Model, SheetKind, SpecRef, Stmt } from '../../src/rpg/types.js';

function ref(seqno: number, sheet: SheetKind, page: string, cardNo: string): SpecRef {
  return { seqno, sheet, page, cardNo };
}

function cond(indicator: string, negated = false): Condition {
  return { indicator, negated };
}

function recordSource(recordType: string, end: number, sourceLength: number, numeric = false) {
  return {
    kind: 'record' as const,
    recordType,
    end,
    sourceLength,
    numeric,
    operation: 'move' as const,
    conditions: [],
  };
}

function pageSource() {
  return {
    kind: 'page' as const,
    numeric: false,
    operation: 'move' as const,
    conditions: [],
  };
}

function k(literal: string, end: number, at: SpecRef): FieldEntry {
  return { kind: 'K', literal, end, conditionGroups: [], zeroSuppress: false, at };
}

function f(name: string, end: number, at: SpecRef, zeroSuppress = false, literal?: string): FieldEntry {
  return {
    kind: 'F', name, end, conditionGroups: [], zeroSuppress,
    ...(literal === undefined ? {} : { literal }),
    at,
  };
}

function b(name: string, end: number, literal: string, at: SpecRef): FieldEntry {
  return { kind: 'B', name, end, literal, conditionGroups: [], zeroSuppress: false, at };
}

function w(name: string, length: number, literal: string, at: SpecRef): FieldEntry {
  return { kind: 'W', name, length, literal, conditionGroups: [], zeroSuppress: false, at };
}

function stmt(label: string, indent: boolean, op: string, operands: readonly string[], comment?: string): Stmt {
  return {
    ...(label === '' ? {} : { label }),
    ...(indent ? { indent } : {}),
    op,
    operands,
    ...(comment === undefined ? {} : { comment }),
  };
}

function comment(text: string): Stmt {
  return { kind: 'comment', op: '', operands: [], comment: text };
}

